function srcGet(key){return srcAll().find(s=>s.key===key)||null;}
function srcRow(s){return{key:s.key,data:srcClean(s),updated_at:s.updatedAt||nowIso(),updated_by:s.updatedBy||''};}
/* b260: fields starting "_" are scratch for the open run (Replen's kept list _sf — 2,000+ ASINs — and _sfMini). They were being saved with the filter, locally and to
   the shared row, so the next day Replen opened showing yesterday's "2,175 kept" and EU buttons before any export. They stay in memory only now. */
function srcClean(s){const o={};Object.keys(s||{}).forEach(k=>{if(k[0]!=='_')o[k]=s[k];});return o;}
function srcSave(src,direct){src.updatedAt=nowIso();src.updatedBy=me();const v=srcAll();const i=v.findIndex(s=>s.key===src.key);const keep=srcClean(src);if(i<0)v.push(keep);else v[i]=keep;lsSet(SRC_KEY,v);
  if(direct&&cloudEnabled()&&cloud.tables){try{cloudReq('POST','src_sources',[srcRow(src)],'resolution=merge-duplicates,return=minimal',true);}catch(e){}return;}
  cloudQueue('src_sources','upsert',[srcRow(src)]);}
function srcRemove(key){lsSet(SRC_KEY,srcAll().filter(s=>s.key!==key));cloudQueue('src_sources','delete',{col:'key',vals:[key]});}
/* in-progress lock: shows on the list so two people do not review the same run. Expires after 4 hours. */
const LOCK_H=4;
function lockFresh(s){return!!(s&&s.inProgress&&s.inProgress.at&&Date.now()-new Date(s.inProgress.at).getTime()<LOCK_H*3600e3);}
/* this browser's own id, so its own lock is never reported as "someone else" even with no name picked */
function lockId(){let v=lsGet('bdl-sourcing-lockid','');if(!v){v=Math.random().toString(36).slice(2,10);lsSet('bdl-sourcing-lockid',v);}return v;}
function ownLock(s){return!!(s&&s.inProgress&&(s.inProgress.id===lockId()||(me()&&s.inProgress.who===me())));}
function otherLock(s){return lockFresh(s)&&!ownLock(s)?s.inProgress:null;}
function srcLock(s){const who=me()||'someone (no name picked)',at=nowIso();s.inProgress={who,at,id:lockId()};
  /* b200 (Jack, 28 Sep: "why haven't they updated — add in who ran it and when"). Opening a source is not a run (a run needs the Keepa export
     dropped in), so the VAs' work never showed. Every open is now kept — who and when, last 30 — and the row says it until a run lands. */
  s.opens=[{who,at}].concat((s.opens||[]).filter(o=>o&&o.at)).slice(0,30);srcSave(s);}
/* the latest open that no run has caught up with yet (null once an export is dropped after it) */
function openSinceRun(s){const o=[(s.opens||[])[0],s.inProgress].filter(x=>x&&x.at).sort((a,b)=>new Date(b.at)-new Date(a.at))[0];if(!o)return null;const last=runLast(s.key);
  /* b250 (Jack's Remington row, 3 Oct: "NOT FINISHED — files in by Jack 21:43" and "Opened 21:43 · not run yet — no file dropped back in" on
     the same row): going back into a filter after its run was saved is looking at the leads, not a missing export — a run saved the same day covers it */
  if(last&&new Date(last.at).toDateString()===new Date(o.at).toDateString())return null;
  return(!last||new Date(o.at)>new Date(last.at))?o:null;}
function srcUnlock(s,direct){if(!s||!s.inProgress)return;delete s.inProgress;srcSave(s,direct);}
function srcKeyFor(name){return name.trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
/* sorted: filters first, then brands A-Z */
/* b32: due now sits at the top of each group, then soonest next run, then name */
function dueRank(s){return dueState(s).rank;}
function srcSorted(){return srcAll().sort((a,b)=>(a.type===b.type?0:a.type==='filter'?-1:1)||(dueRank(a)-dueRank(b))||a.name.localeCompare(b.name));}
/* Keepa Product Finder link for a brand: the brand strings + Amazon down 9%+ vs its 90-day average.
   The link carries no marketplace — Keepa runs it on whichever locale is selected, so one link does all five. */
/* b110 (Jack, 18 Sep: "ye" to the rank month rolling by itself). Keepa's "sales rank average month" is pinned inside the saved
   link (srAvgMonth). Suz's A2A filter was still on 202509 = September 2025, a year stale, and 25 others sit on 202608. The stored link
   is left alone; the link that OPENS has the month swapped for the last complete month, so nobody has to re-pin anything again. */
function lastFullMonth(d){d=d||new Date();const y=d.getFullYear(),m=d.getMonth();const py=m===0?y-1:y,pm=m===0?12:m;return String(py)+String(pm).padStart(2,'0');}
function rollRankMonth(link,d){if(!link)return link;const ym=lastFullMonth(d);
  return link.replace(/(srAvgMonth%22%3A%7B%22filterType%22%3A%22text%22%2C%22type%22%3A%22equals%22%2C%22filter%22%3A%22)\d{6}/g,'$1'+ym)
             .replace(/("srAvgMonth":\{"filterType":"text","type":"equals","filter":")\d{6}/g,'$1'+ym);}
/* b210 (Jack, 29 Sep: "just have the buy link as Amazon's ID for that country"): Buy DE / FR / IT / ES / UK opens the listing on Amazon's own
   offer there (?m=<Amazon's seller ID>), not whoever holds the Buy Box. Done where the link is drawn, so rule1.js stays frozen. */
const AMZ_SELLER={UK:'A3P5ROKL5A1OLE',DE:'A3JWKAKR8XB7XF',FR:'A1X6FK5RDHNB96',IT:'A11IL2PNWYJU7H',ES:'A1AT7YVPFBWXBL'};
const AMZ_TLD_MK={'co.uk':'UK',de:'DE',fr:'FR',it:'IT',es:'ES'};
function amzBuyLink(url){const m=/^https:\/\/www\.amazon\.(co\.uk|de|fr|it|es)\/dp\/([A-Z0-9]{10})\/?$/.exec(String(url||''));if(!m)return url||'';
  return`https://www.amazon.${m[1]}/dp/${m[2]}?m=${AMZ_SELLER[AMZ_TLD_MK[m[1]]]}`;}
/* b234: a source can carry a second Keepa filter (the coupon one: % off + £ off) — both open, both exports drop into the one run */
function finderLinks(src){const L=[];const a=finderLink(src);if(a)L.push({lab:src.linkLab||'the filter',url:a});if(src.link2)L.push({lab:src.link2Lab||'2nd filter',url:rollRankMonth(src.link2)});return L;}
const CURTAIN_NODES=['3028602031','3028604031'],NO_CATS_FILTERS=['curtains & drapes'];   /* Home & Kitchen › Home Accessories › Window Treatments › Curtains & Drapes › Panels */
function linkAddCats(l,nodes){if(!l||typeof l!=='string')return l;const m=/^(.*#!finder\/)(.+)$/.exec(l);if(!m)return l;let j;try{j=JSON.parse(decodeURIComponent(m[2]));}catch(e){return l;}
  const f=j.f||(j.f={});if(f.categories||f.sellerIds)return l;   /* an include list / a storefront: nothing to take out */
  const cur=f.categories_exclude&&f.categories_exclude.filter?String(f.categories_exclude.filter).split('###').filter(Boolean):[];const add=nodes.filter(n=>!cur.includes(n));
  if(!add.length||cur.length+add.length>50)return l;
  f.categories_exclude={filterType:'autocomplete',filter:cur.concat(add).join('###'),type:'isOneOf'};
  return m[1]+encodeURIComponent(JSON.stringify(j)).replace(/'/g,'%27');}
function link9(l){if(!l||typeof l!=='string')return l;const m=/^(.*#!finder\/)(.+)$/.exec(l);if(!m)return l;let j;try{j=JSON.parse(decodeURIComponent(m[2]));}catch(e){return l;}
  const f=j.f||{};let ch=false;['salesRankDrops30','monthlySold'].forEach(k=>{const c=f[k];if(c&&c.type==='greaterThanOrEqual'&&+c.filter===10){c.filter=9;ch=true;}});
  return ch?m[1]+encodeURIComponent(JSON.stringify(j)):l;}
function finderLink(src){if(src.link)return rollRankMonth(src.link);if(src.type==='filter')return'';
  const brands=(src.brands&&src.brands.length?src.brands:[src.name]).map(b=>b.toLowerCase()).join('###');
  const f={brand:{filterType:'autocomplete',filter:brands,type:'isOneOf'},
    AMAZON_deltaPercent90:{filterType:'number',type:'greaterThanOrEqual',filter:9,filterTo:null},
    productType:{values:['0'],filterType:'set'}};
  return 'https://keepa.com/#!finder/'+encodeURIComponent(JSON.stringify({f,s:[{colId:'AMAZON_deltaPercent90',sort:'desc'}],t:'g'}));}

/* ---- run log: one row per export processed per source per day. This is the 7-day count. ---- */
const RUN_KEY='bdl-sourcing-runs';
function runsAll(){return lsGet(RUN_KEY,[]);}
function runsFor(key){return runsAll().filter(r=>r.source===key);}
function runLast(key){const r=runsFor(key);return r.length?r[r.length-1]:null;}
/* b260 (Jack, 4 Oct, at an amber NOT FINISHED row from the night before: "not finished — if left for over 12 hours goes back to not done and needs to be
   redone"). A run whose files went in but nobody pressed ✓ Done counts for 12 hours. After that it does not count as a run at all: the filter is judged on
   the last run that WAS finished, so it goes back to NOT DONE / due and has to be run again with fresh files. Runs saved before b244 never needed the press. */
const STALE_H=12;
function runStale(r){return!!(r&&r.needDone&&!r.done&&Date.now()-new Date(r.at).getTime()>STALE_H*3600e3);}
function runLastOk(key){const R=runsFor(key);for(let i=R.length-1;i>=0;i--){if(!runStale(R[i]))return R[i];}return null;}
function runSave(run){const runs=runsAll().filter(r=>!(r.source===run.source&&(r.day||r.at.slice(0,10))===run.day));runs.push(run);lsSet(RUN_KEY,runs);
  cloudQueue('src_runs','upsert',[{id:run.source+'|'+run.day,source_key:run.source,day:run.day,at:run.at,who:run.who||'',data:run}]);}
/* b139 (Jack, 21 Sep — does an API run count as the VA's run? "not until they worked it"): Jack's Keepa API look is his own.
   It is never the source's run: no src_runs row, so ShiftTrack never sees it, the due date and the new/better compare
   baseline stay exactly where the VA's last export left them. It lives only in this browser, one per source, the newest. */
const API_LOOK_KEY='bdl-sourcing-api-looks';
function apiLookAll(){return lsGet(API_LOOK_KEY,{});}
function apiLookFor(key){return apiLookAll()[key]||null;}
function apiLookSave(key,look){const all=apiLookAll();all[key]=look;lsSet(API_LOOK_KEY,all);}
function apiLookForget(key){const all=apiLookAll();if(!all[key])return;delete all[key];lsSet(API_LOOK_KEY,all);}
function runsForget(key){const gone=runsFor(key);lsSet(RUN_KEY,runsAll().filter(r=>r.source!==key));cloudQueue('src_runs','delete',{col:'id',vals:gone.map(r=>r.source+'|'+(r.day||r.at.slice(0,10)))});}
const STATUS_LABEL={active:'Active',testing:'Testing',paused:'Paused'};
/* Keepa API cost if this run were automated: 10 per Finder query + 1 per ASIN pulled. Manual export = 0. */
function tokenEstimate(src){const last=runLast(src.key);const rowsIn=last?last.rowsIn:(src.type==='filter'?520:400);
  if(src.type==='filter')return 10+rowsIn;
  const eu=src.markets.filter(m=>m!=='UK').length;return 10*src.markets.length+rowsIn+Math.round(eu*rowsIn*0.25);}
function nextRun(src){const last=runLastOk(src.key);const days=CADENCE_DAYS[src.cadence];if(!last||!days)return null;
  const d=new Date(last.at);d.setDate(d.getDate()+days);d.setHours(7,0,0,0);return d;}
/* b46 (Jack, 15 Sep): "next run if today should be red as due today, overdue red too, the whole line red; if done today greyed out" */
function dueState(src){if(src.status==='paused')return{label:'Paused',cls:'paused',due:false,rank:9000};
  const lastAny=runLast(src.key),last=runLastOk(src.key),stale=runStale(lastAny)?lastAny:null;const days=CADENCE_DAYS[src.cadence];   /* b260: an unfinished run over 12 hours old does not count */
  const out=o=>{if(stale)o.stale=stale;return o;};
  /* b154 (Jack, 25 Sep: "improve font and UI UX design of due now and overdue"): plain words, and the latest runs come first.
     kind = late / today / first, so the pill, the row and the counts can tell them apart; rank −days puts 9 days late above 1 day late */
  if(!last)return out({label:stale?'Run it again':'First run',cls:'due first',kind:'first',due:true,rank:2,sub:stale?'not finished within '+STALE_H+' hours':'never run yet'});
  const lastDay=String(last.at).slice(0,10),t=today();
  const nx=new Date(last.at);nx.setDate(nx.getDate()+(days||0));nx.setHours(7,0,0,0);const nxDay=nx.toISOString().slice(0,10);
  const nice=nx.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});
  if(lastDay===t)return out({label:'Done today',cls:'done',due:false,rank:8000,sub:days?'next '+nice:'one-off'});
  if(!days)return out({label:'One-off',cls:'',due:false,rank:5000});
  if(nxDay<t){const od=Math.round((new Date(t)-new Date(nxDay))/864e5);return out({label:od===1?'1 day late':od+' days late',cls:'due late',kind:'late',late:od,due:true,rank:-od,sub:'was due '+nice});}
  if(nxDay===t)return out({label:'Due today',cls:'due today',kind:'today',due:true,rank:1});
  const inD=Math.round((new Date(nxDay)-new Date(t))/864e5);return out({label:nice,cls:'ok',due:false,rank:100+inD,sub:inD===1?'tomorrow':'in '+inD+' days'});}
function fmtWhen(iso){const d=new Date(iso);const t=new Date();const sameDay=d.toDateString()===t.toDateString();
  const y=new Date(t);y.setDate(t.getDate()-1);const yest=d.toDateString()===y.toDateString();
  const hm=d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
  return(sameDay?'Today':yest?'Yesterday':d.toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'}))+' '+hm;}

/* ---- lead states per source (b10): the shared compare baseline. {source:{asin:{state,stamp,prev}}} ---- */
const LEAD_KEY='bdl-sourcing-leadstate';
function leadAll(){return lsGet(LEAD_KEY,{});}
function leadMap(key){const all=leadAll();if(all[key])return all[key];
  /* one-time: b9 kept per-day snapshots in bdl-sourcing-history — the newest previous-day one becomes the baseline */
  const h=(lsGet('bdl-sourcing-history',{})||{})[key];if(!h||!h.length)return{};
  const snapRow=h.slice().reverse().find(x=>x.stamp.slice(0,10)!==today())||h[h.length-1];const m={};
  Object.entries(snapRow.snap||{}).forEach(([a,p])=>{m[a]={state:{buy:p['Landed £'],sell:p['Sell £ used'],profit:p['Profit £'],roi:p['ROI %'],spm:p.SPM,score:p.Score,disc:'',mk:p['Buy market']||'UK'},stamp:snapRow.stamp,prev:null};});
  all[key]=m;lsSet(LEAD_KEY,all);return m;}
function leadSave(key,map){const all=leadAll();const old=all[key]||{};all[key]=map;lsSet(LEAD_KEY,all);
  const rows=Object.entries(map).map(([a,e])=>({id:key+'|'+a,source_key:key,asin:a,state:e.state,stamp:e.stamp,prev:e.prev||null,updated_at:nowIso()}));
  const gone=Object.keys(old).filter(a=>!map[a]).map(a=>key+'|'+a);
  cloudQueue('src_leads','upsert',rows);cloudQueue('src_leads','delete',{col:'id',vals:gone});}
function histForget(key){const all=leadAll();const old=all[key]||{};delete all[key];lsSet(LEAD_KEY,all);
  cloudQueue('src_leads','delete',{col:'id',vals:Object.keys(old).map(a=>key+'|'+a)});lsRemove('bdl-sourcing-history');}

/* ---- verdicts: who said what about an ASIN. The learning layer, test-mode edition. ---- */
const VERD_KEY='bdl-sourcing-verdicts',ME_KEY='bdl-sourcing-me',REASONS_KEY='bdl-sourcing-reasons';
const NO_REASONS_DEFAULT=['price wrong','not a real drop','too slow','margin too thin','other'];
const USERS=['Jack','Mera','Suz'];
/* b126 (Jack, 20 Sep: "put all brands onto n/a so I can choose - I don't want VAs seeing all of the stuff yet"): a source with no owner belongs to nobody and shows in no VA's list. */
const NO_OWNER='—';
const OWNER_OPTS=['Jack','Mera','Suz','VAs',NO_OWNER];
function noReasons(){return lsGet(REASONS_KEY,NO_REASONS_DEFAULT);}
function settingRow(key,value){return{key,value,updated_at:nowIso(),updated_by:me()};}
function reasonsSave(list){lsSet(REASONS_KEY,list);cloudQueue('src_settings','upsert',[settingRow('reasons',list)]);}
function vat0Save(words){lsSet(VAT0_KEY,words);cloudQueue('src_settings','upsert',[settingRow('vat0',words)]);}
function me(){return lsGet(ME_KEY,'');}
function isJack(){return me()==='Jack';}
/* b132 (Jack, 21 Sep: "Mera shouldn't see Suz's and Suz shouldn't see Mera's"). One rule, used by every list:
   Jack sees everything; anyone else sees the sources that are theirs, and nothing else. A source with no owner
   belongs to nobody yet (Jack hands it out), so it is his alone until he does.
   A link someone was sent still opens — being sent a source is different from browsing other people's. */
function canSee(src){if(!src)return false;if(isJack())return true;const m=me();if(!m)return false;
  if(src.owner===m)return true;
  if(src.owner==='VAs')return true;   /* b133: "VAs" means both of them on purpose — the label says so. Unowned is the private one. */
  if(typeof lockFresh==='function'&&lockFresh(src)&&typeof ownLock==='function'&&ownLock(src))return true;
  return false;}
function visibleSources(){return srcAll().filter(canSee);}
function verdAll(){return lsGet(VERD_KEY,{});}
function verdGet(asin){return verdAll()[asin]||null;}
/* b232 (Jack, 1 Oct: "I don't care if Suz reviews one filter and Mera another — don't hide it from Mera because Suz saw the same ASIN somewhere else").
   The products YOU answered today, kept in this browser only. There is one verdict per product (the last answer wins), so without this
   Suz answering an ASIN after Mera would un-tick it on Mera's list. */
const MINE_KEY='bdl-sourcing-mine-today';let MINE=null;
function myToday(){const t=today(),w=me();if(!MINE||MINE.day!==t||MINE.who!==w){const m=lsGet(MINE_KEY,null);MINE={day:t,who:w,a:new Set(m&&m.day===t&&m.who===w?m.a:[])};}return MINE.a;}
function myTodayEdit(asins,add){const s=myToday();(asins||[]).forEach(a=>add?s.add(a):s.delete(a));lsSet(MINE_KEY,{day:MINE.day,who:MINE.who,a:[...s]});}
/* v = {v:'Yes'|'No'|'Maybe', reason, note, source, state} — state is the lead's numbers at the moment of the verdict; that is what "better since" compares against */
/* b143 (Jack, 22 Sep: "what is the fix and improvement to make sure it never happens again"). Every verdict now records HOW it was
   written — a row's Y/N/M, the keyboard, or a bulk button by name. b142's bug was a button writing 82 verdicts as a side effect of
   looking, and nothing on the row could tell you that. `via` is kept in this browser only: src_verdicts has no such column, and
   sending one it does not know is what broke the audit sync in b109. */
function verdSet(asin,v,via){const a=verdAll();
  if(!v){delete a[asin];lsSet(VERD_KEY,a);myTodayEdit([asin],false);cloudQueue('src_verdicts','delete',{col:'asin',vals:[asin]});return;}
  const row=Object.assign({at:nowIso(),who:me(),via:via||'the row'},v);a[asin]=row;lsSet(VERD_KEY,a);myTodayEdit([asin],true);
  cloudQueue('src_verdicts','upsert',[{asin,v:row.v,reason:row.reason||'',note:row.note||'',who:row.who||'',at:row.at,source_key:row.source||'',state:row.state||null}]);}
/* many at once (the "mark all as seen" baseline) — one queued write, not hundreds */
function verdSetMany(items,via){const a=verdAll();const at=nowIso(),who=me();const rows=[];
  items.forEach(({asin,v})=>{const row=Object.assign({at,who,via:via||'a bulk button'},v);a[asin]=row;rows.push({asin,v:row.v,reason:row.reason||'',note:row.note||'',who,at,source_key:row.source||'',state:row.state||null});});
  lsSet(VERD_KEY,a);myTodayEdit(items.map(x=>x.asin),true);cloudQueue('src_verdicts','upsert',rows);}

/* b233: Open in Keepa (a VA) and the Done button count as done. A lead with no answer, or only a Seen, gets a fresh Seen under your name.
   A lead that already has a real Yes / No / Maybe KEEPS it (the audit, the lead-sheet week and Jack's calls read those) — who looked and
   when goes in state.seen = {Name:{at,src}} on the same row instead. */
function seenStampMany(items,via){const a=verdAll();const at=nowIso(),who=me();const rows=[];
  items.forEach(({asin,v})=>{const old=a[asin];let row;
    if(old&&old.v&&old.v!=='Seen'){const st=Object.assign({},old.state||{});st.seen=Object.assign({},st.seen||{},{[who]:{at,src:v.source||''}});row=Object.assign({},old,{state:st});}
    else row=Object.assign({at,who,via:via||'a bulk button'},v);
    a[asin]=row;rows.push({asin,v:row.v,reason:row.reason||'',note:row.note||'',who:row.who||'',at:row.at,source_key:row.source||'',state:row.state||null});});
  lsSet(VERD_KEY,a);myTodayEdit(items.map(x=>x.asin),true);if(rows.length)cloudQueue('src_verdicts','upsert',rows);}
/* b233: undo — clears the looked-at stamps a source put on real answers (the answers themselves stay) */
function seenUnstampMany(asins,src){const a=verdAll();const rows=[];
  (asins||[]).forEach(x=>{const r=a[x];const sn=r&&r.state&&r.state.seen;if(!sn)return;const keep={};let hit=false;
    Object.entries(sn).forEach(([w,e])=>{if(e&&e.src===src)hit=true;else keep[w]=e;});if(!hit)return;
    const st=Object.assign({},r.state);if(Object.keys(keep).length)st.seen=keep;else delete st.seen;a[x]=Object.assign({},r,{state:st});
    rows.push({asin:x,v:r.v,reason:r.reason||'',note:r.note||'',who:r.who||'',at:r.at,source_key:r.source||'',state:st});});
  if(!rows.length)return 0;lsSet(VERD_KEY,a);myTodayEdit(rows.map(r=>r.asin),false);cloudQueue('src_verdicts','upsert',rows);return rows.length;}

/* b142 (Jack, 22 Sep): take a verdict back off a lead — used by "put them back in the queue" */
function verdDelMany(asins){const a=verdAll();const gone=[];
  (asins||[]).forEach(x=>{if(a[x]){delete a[x];gone.push(x);}});
  if(!gone.length)return 0;lsSet(VERD_KEY,a);myTodayEdit(gone,false);cloudQueue('src_verdicts','delete',{col:'asin',vals:gone});return gone.length;}

/* ---- ASIN facts: what a VA has confirmed about a product. Test-mode edition of the knowledge layer. ---- */
const FACT_KEY='bdl-sourcing-facts';
const PM_OPTIONS=['Currys','Argos','John Lewis','Brand direct'];
/* b206 (Jack, 29 Sep: "the cache should start to learn which ASINs they have S&S on and don't, if we are saving data"; and "if Amazon are on
   it, it tends to have Subscribe & Save — most FBA sellers won't"). Every UK export teaches the shared facts: sns.y = the last day the Buy
   Box showed Subscribe & Save, sns.n = the last day AMAZON held the Buy Box with none (a real "no"; a 3P seller without S&S proves nothing).
   Rule 2 then counts S&S on a row whose export says no when the ASIN was seen with it inside SNS_MEMORY_DAYS, Amazon is selling it now,
   and Amazon has not been seen without it since. One batched write per run, only for what changed. */
const SNS_MEMORY_DAYS=120;
function snsLearn(rows){if(!rows||!rows.length)return 0;const a=factsFresh(),day=today(),up=[];
  rows.forEach(r=>{const asin=(r.ASIN||'').trim();if(!/^B[0-9A-Z]{9}$/.test(asin))return;
    const yes=typeof r2hasSS==='function'&&r2hasSS(r);const amzBB=/^amazon/i.test((r['Buy Box: Buy Box Seller']||'').trim());
    if(!yes&&!amzBB)return;const f=a[asin]||{};const sn=Object.assign({},f.sns||{});
    if(yes){if(sn.y===day)return;sn.y=day;}else{if(sn.n===day)return;sn.n=day;}
    a[asin]=Object.assign({},f,{sns:sn,at:nowIso(),who:f.who||me()||''});up.push(asin);});
  if(!up.length)return 0;lsSet(FACT_KEY,a);
  if(typeof cloudQueue==='function')cloudQueue('src_facts','upsert',up.map(asin=>{const {who,at,...data}=a[asin];return{asin,data,who:who||'',at};}));
  return up.length;}
/* seen with S&S recently, and Amazon not seen holding the Buy Box without it since */
function snsRemembered(fact){const sn=fact&&fact.sns;if(!sn||!sn.y)return null;if(sn.n&&sn.n>sn.y)return null;
  const age=(Date.parse(today())-Date.parse(sn.y))/864e5;return age<=SNS_MEMORY_DAYS?sn.y:null;}
/* b275 (Jack, 6 Oct: "super buggy and laggy — dropping and it loading to the leads"): this store is ~600 KB and grows with every export
   (snsLearn). Drawing the leads unpacked it 1,300 times — once or more per row — and every Y/N/M press redraws the table, so each drop and
   each click froze the page for seconds. Unpack it once and reuse it until the stored text changes. Readers never write into it; the two
   writers (snsLearn, factSet) take their own fresh copy. */
let FACTS_C={raw:undefined,v:null};
function factsAll(){const raw=lsRaw(FACT_KEY);if(!FACTS_C.v||raw!==FACTS_C.raw)FACTS_C={raw,v:lsGet(FACT_KEY,{})};return FACTS_C.v;}
function factsFresh(){return lsGet(FACT_KEY,{});}
function factGet(asin){return factsAll()[asin]||{};}
function factSet(asin,f){const a=factsFresh();const clean=Object.assign({},a[asin]||{},f,{at:nowIso(),who:me()});
  Object.keys(clean).forEach(k=>{if(clean[k]==null||clean[k]==='')delete clean[k];});
  const empty=!(clean.pm&&clean.pm.length)&&!clean.sell&&!clean.note&&clean.vat==null&&!clean.track&&!clean.sns;
  if(empty){delete a[asin];lsSet(FACT_KEY,a);cloudQueue('src_facts','delete',{col:'asin',vals:[asin]});return;}
  a[asin]=clean;lsSet(FACT_KEY,a);const {who,at,...data}=clean;cloudQueue('src_facts','upsert',[{asin,data,who:who||'',at}]);}

